INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Edge Computing dasselbe wie Cloud Computing?', 2, '[{"text": "Nein", "correct": true, "because": "Dezentral vs. zentral"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Ansätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt Edge Computing?', 3, '[{"text": "Datenverarbeitung nah am Entstehungsort", "correct": true, "because": "Latenz reduzieren"}, {"text": "Zentrale Datenlagerung", "correct": false, "because": "Cloud-Fokus"}, {"text": "Hardware-Optimierung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat Edge Computing?', 5, '[{"text": "Dezentralisierung", "correct": true, "because": "Nah an Geräten"}, {"text": "Niedrige Latenz", "correct": true, "because": "Schnelle Verarbeitung"}, {"text": "Zentraler Server", "correct": false, "because": "Cloud-Eigenschaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Edge Computing reduziert Latenz. b) Es ersetzt die Cloud vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cloud ergänzend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Edge Computing?', 4, '[{"text": "Netzwerklatenz", "correct": false, "because": "Kernvorteil"}, {"text": "Datenverarbeitung", "correct": false, "because": "Hauptfunktion"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Edge Computing nur für IoT ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Anwendungen"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie nutzt Edge Computing oft?', 3, '[{"text": "IoT-Geräte", "correct": true, "because": "Datenquellen"}, {"text": "Zentraler Mainframe", "correct": false, "because": "Nicht dezentral"}, {"text": "Papierdokumente", "correct": false, "because": "Digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Edge Computing?', 5, '[{"text": "Schnellere Reaktionszeit", "correct": true, "because": "Latenzreduktion"}, {"text": "Weniger Bandbreitenbedarf", "correct": true, "because": "Lokale Verarbeitung"}, {"text": "Zentrale Datenspeicherung", "correct": false, "because": "Dezentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Edge Computing verarbeitet Daten lokal. b) Es benötigt immer eine Cloud. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cloud optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Edge Computing?', 4, '[{"text": "Edge-Geräte", "correct": false, "because": "Verarbeitungsort"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Datenfluss"}, {"text": "Physische Serverräume", "correct": true, "because": "Dezentral möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Edge Computing unabhängig von der Cloud?', 2, '[{"text": "Ja", "correct": true, "because": "Kann eigenständig"}, {"text": "Nein", "correct": false, "because": "Oft ergänzend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen nutzen Edge Computing?', 4, '[{"text": "Smart Cities", "correct": true, "because": "Lokale Verarbeitung"}, {"text": "Autonomes Fahren", "correct": true, "because": "Echtzeit"}, {"text": "Papierarchivierung", "correct": false, "because": "Nicht digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Edge Computing nur für große Firmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs"}, {"text": "Ja", "correct": false, "because": "Skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Edge Computing?', 3, '[{"text": "Latenzreduktion", "correct": true, "because": "Schnelle Verarbeitung"}, {"text": "Zentrale Speicherung", "correct": false, "because": "Dezentral"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Edge Computing spart Bandbreite. b) Es ist langsamer als Cloud Computing.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schneller lokal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte sind typisch für Edge Computing?', 5, '[{"text": "IoT-Sensoren", "correct": true, "because": "Datenquellen"}, {"text": "Edge-Server", "correct": true, "because": "Verarbeitung"}, {"text": "Zentrale Mainframes", "correct": false, "because": "Cloud-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Edge Computing unwichtig?', 3, '[{"text": "Datenverarbeitung", "correct": false, "because": "Kernmerkmal"}, {"text": "Latenz", "correct": false, "because": "Entscheidend"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Edge Computing ohne Netzwerkverbindung laufen?', 3, '[{"text": "Ja", "correct": true, "because": "Lokale Verarbeitung"}, {"text": "Nein", "correct": false, "because": "Unabhängig möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Edge Computing Sicherheitsrisiken erhöht?', 2, '[{"text": "Ja", "correct": true, "because": "Mehr Angriffspunkte"}, {"text": "Nein", "correct": false, "because": "Risiken steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Edge Computing zentral?', 4, '[{"text": "Dezentrale Verarbeitung", "correct": true, "because": "Kernprinzip"}, {"text": "Zentrale Speicherung", "correct": false, "because": "Cloud"}, {"text": "Physische Größe", "correct": false, "because": "Irrelevant"}]');
